import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(import.meta.dirname, '..');
const blogs = fs.readdirSync(path.join(root, 'blogs'))
  .filter(name => /^\d+\.html$/.test(name))
  .sort((a, b) => Number.parseInt(a) - Number.parseInt(b));
const lines = [
  '# Generated by scripts/generate-redirects.mjs',
  '/index.html  /  301!',
  '/privacy.html  /privacy  301!',
  '/terms-and-conditions.html  /terms-and-conditions  301!',
  ...blogs.map(name => `/blogs/${name}  /blogs/${name.replace('.html', '')}  301!`)
];

fs.writeFileSync(path.join(root, '_redirects'), `${lines.join('\n')}\n`);
console.log(`Generated _redirects with ${lines.length - 1} canonical URL rules.`);
